// AUTO-GENERATED by scripts/sync-web.mjs from the website source. Do not edit here.
// SKY VIP fee schedule. Tiers, thresholds and maker/taker rates mirror OKX's
// standard USD schedule (OKX notice published 2026-08-20, effective 2026-09-09;
// cross-checked against a third-party table checked 2026-11-10).
// A tier is reached by meeting EITHER the asset OR the 30-day volume threshold.
// Spot and futures tiers are assessed separately (volume thresholds differ).
// Rates are fractions (0.0008 = 0.08%). Negative maker = rebate.

export type Market = 'spot' | 'perp'
export type Tier = {
  level: number // 0 = Regular
  minAssets: number // USD
  minVolume: Record<Market, number> // 30-day USD volume in that market
  maker: Record<Market, number>
  taker: Record<Market, number>
}

const row = (level: number, assets: number, spotVol: number, perpVol: number,
  spotMaker: number, spotTaker: number, perpMaker: number, perpTaker: number): Tier => ({
  level, minAssets: assets,
  minVolume: { spot: spotVol, perp: perpVol },
  maker: { spot: spotMaker / 100, perp: perpMaker / 100 },
  taker: { spot: spotTaker / 100, perp: perpTaker / 100 },
})

const M = 1e6, B = 1e9
export const TIERS: Tier[] = [
  row(0, 0, 0, 0, 0.08, 0.10, 0.02, 0.05),
  row(1, 100_000, 1 * M, 5 * M, 0.0675, 0.08, 0.016, 0.045),
  row(2, 200_000, 5 * M, 10 * M, 0.06, 0.07, 0.015, 0.036),
  row(3, 2 * M, 10 * M, 50 * M, 0.055, 0.065, 0.01, 0.028),
  row(4, 5 * M, 20 * M, 200 * M, 0.03, 0.045, 0.008, 0.027),
  row(5, 20 * M, 100 * M, 600 * M, 0.025, 0.035, 0.005, 0.026),
  row(6, 50 * M, 200 * M, 1 * B, 0, 0.03, 0, 0.025),
  row(7, 100 * M, 500 * M, 1.5 * B, -0.001, 0.023, -0.001, 0.023),
  row(8, 250 * M, 1 * B, 2 * B, -0.0025, 0.02, -0.0025, 0.02),
  row(9, 500 * M, 5 * B, 20 * B, -0.005, 0.015, -0.005, 0.015),
]

export function tierFor(market: Market, assetsUsd: number, volume30d: number): Tier {
  let t = TIERS[0]
  for (const x of TIERS) if (assetsUsd >= x.minAssets || volume30d >= x.minVolume[market]) t = x
  return t
}

export const nextTier = (t: Tier): Tier | undefined => TIERS[t.level + 1]

/** Fee for one fill. Negative result = rebate paid to the user. */
export const feeFor = (notional: number, rate: number) => notional * rate

export const pct = (rate: number) => `${rate < 0 ? '−' : ''}${Math.abs(rate * 100).toFixed(4)}%`

/** What the VIP tiers need to know about an account (the /account reply). */
export type VipSource = {
  total?: number
  vip?: { spot: number; perp: number; assets: number; vol30Spot: number; vol30Perp: number
    spotMaker: number; spotTaker: number; perpMaker: number; perpTaker: number }
}
export type MyVip = { spot: Tier; perp: Tier; level: number; assetsUsd: number; volume30d: Record<Market, number> }

/** The account's spot and perpetual tiers, with the rates the server charges. Regular when logged out. */
export function vipOf(a?: VipSource): MyVip {
  const v = a?.vip
  if (!v) {
    const assetsUsd = a?.total ?? 0
    const spot = tierFor('spot', assetsUsd, 0), perp = tierFor('perp', assetsUsd, 0)
    return { spot, perp, level: Math.max(spot.level, perp.level), assetsUsd, volume30d: { spot: 0, perp: 0 } }
  }
  const at = (l: number) => TIERS[Math.max(0, Math.min(TIERS.length - 1, l))]
  const spot = { ...at(v.spot), maker: { ...at(v.spot).maker, spot: v.spotMaker }, taker: { ...at(v.spot).taker, spot: v.spotTaker } }
  const perp = { ...at(v.perp), maker: { ...at(v.perp).maker, perp: v.perpMaker }, taker: { ...at(v.perp).taker, perp: v.perpTaker } }
  return { spot, perp, level: Math.max(v.spot, v.perp), assetsUsd: v.assets, volume30d: { spot: v.vol30Spot, perp: v.vol30Perp } }
}
